package com.acme.billing;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InvoiceCancellationService {

    private final InvoiceRepository invoiceRepository;

    public InvoiceCancellationService(InvoiceRepository invoiceRepository) {
        this.invoiceRepository = invoiceRepository;
    }

    @Transactional
    public InvoiceDtos.InvoiceCancelled cancel(long invoiceId, long customerId) {
        Invoice invoice = invoiceRepository.findById(invoiceId)
                .filter(i -> i.customerId() == customerId)          // ownership check
                .orElseThrow(() -> new InvoiceNotFoundException(invoiceId));

        if (invoice.status() != InvoiceStatus.UNPAID) {              // state check
            throw new InvoiceNotCancellableException(invoiceId, invoice.status());
        }

        invoice.markCancelled();
        return new InvoiceDtos.InvoiceCancelled(invoiceId, String.valueOf(invoice.status()));
    }
}
